class Solution {
public:
    string findLongestWord(string s, vector<string>& dictionary) {
        int n = s.size();
        // next[i][c] = smallest index j >= i with s[j] == c, or -1
        vector<vector<int>> next(n + 1, vector<int>(26, -1));
        for (int i = n - 1; i >= 0; --i) {
            for (int c = 0; c < 26; ++c)
                next[i][c] = next[i + 1][c];
            next[i][s[i] - 'a'] = i;
        }
        string best;
        for (const string& w : dictionary) {
            int pos = 0;
            bool ok = true;
            for (char ch : w) {
                int idx = next[pos][ch - 'a'];
                if (idx == -1) {
                    ok = false;
                    break;
                }
                pos = idx + 1;
            }
            if (ok && (w.size() > best.size() ||
                       (w.size() == best.size() && w < best))) {
                best = w;
            }
        }
        return best;
    }
};
